import Testing
@testable import CodexPadApplication
@testable import CodexPadDomain
@Test func mcpServerStatusListsStablePagesAndOpaqueCursor() throws { let service=try CodexMCPServerStatusService(statuses:[CodexMCPServerStatus(name:"zeta",authStatus:.oauth),CodexMCPServerStatus(name:"alpha",authStatus:.notLoggedIn)],pageSize:1);let first=try service.list();#expect(first.data.map(\.name)==["alpha"]);let second=try service.list(cursor:first.nextCursor);#expect(second.data.map(\.name)==["zeta"]);#expect(second.nextCursor==nil) }
@Test func mcpServerStatusToolsAndAuthDetailOmitsInventory() throws { let service=try CodexMCPServerStatusService(statuses:[CodexMCPServerStatus(name:"sample",serverInfo:.object(["name":.string("fixture")]),tools:["list":.object(["name":.string("list")])],resources:[CodexMCPResource(uri:"sample://x",name:"x")],authStatus:.bearerToken)]);let page=try service.list(detail:.toolsAndAuthOnly);#expect(page.data[0].tools.keys.sorted()==["list"]);#expect(page.data[0].resources.isEmpty);#expect(page.data[0].serverInfo==nil) }
@Test func mcpServerStatusRejectsBadCursorAndDuplicateNames() throws { #expect(throws:CodexMCPResourceError.self){try CodexMCPServerStatusService(statuses:[CodexMCPServerStatus(name:"same",authStatus:.oauth),CodexMCPServerStatus(name:"same",authStatus:.oauth)])};let service=try CodexMCPServerStatusService(statuses:[CodexMCPServerStatus(name:"sample",authStatus:.oauth)]);#expect(throws:CodexMCPResourceError.self){try service.list(cursor:"bad")} }
